-- =============================================
-- 污染源趋势数据 - 按周/月/季度聚合
-- =============================================

SET NAMES utf8mb4;
USE airquality_db;

-- 创建趋势数据表（如果不存在）
DROP TABLE IF EXISTS source_trend_data;
CREATE TABLE source_trend_data (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    city VARCHAR(50) NOT NULL COMMENT '城市',
    source_type VARCHAR(50) NOT NULL COMMENT '污染源类型',
    period_type VARCHAR(20) NOT NULL COMMENT '周期类型: week/month/quarter',
    period_value VARCHAR(20) NOT NULL COMMENT '周期值: 2024-W01/2024-01/2024-Q1',
    avg_contribution_rate DECIMAL(5,2) NOT NULL COMMENT '平均贡献率',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_city_type_period (city, source_type, period_type, period_value),
    KEY idx_city (city),
    KEY idx_period_type (period_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='污染源趋势数据表';

-- 清空数据
TRUNCATE TABLE source_trend_data;

