-- 验证数据
SELECT '周数据统计:' AS '类型', COUNT(*) AS '记录数' FROM source_trend_data WHERE period_type = 'week'
UNION ALL
SELECT '月数据统计:', COUNT(*) FROM source_trend_data WHERE period_type = 'month'
UNION ALL
SELECT '季度数据统计:', COUNT(*) FROM source_trend_data WHERE period_type = 'quarter';

SELECT '数据预览 - 北京月度趋势:' AS '说明';
SELECT * FROM source_trend_data WHERE city = '北京' AND period_type = 'month' ORDER BY period_value;
